import ee, math
ee.Initialize(project='earthsense-436113')

# 1. Geometry & Time Definitions
date = '2025-06-24'
start = ee.Date(date)
end = start.advance(1, 'day')

st_francis_pt = ee.Geometry.Point([-101.8, 39.77])
death_valley_pt = ee.Geometry.Point([-116.8669, 36.4623])
buffer_m = 15000
st_geom = st_francis_pt.buffer(buffer_m)
dv_geom = death_valley_pt.buffer(buffer_m)

primary_ds = 'ECMWF/ERA5_LAND/HOURLY'
fallback_ds = 'ECMWF/ERA5/HOURLY'
band = 'temperature_2m'

def daily_peak_t2m(geom, name):
    def get(ds):
        return ee.ImageCollection(ds).filterDate(start, end).select(band)
    try:
        col = get(primary_ds)
        n = col.size().getInfo()
        source = 'ERA5-LAND'
        if n == 0:
            col = get(fallback_ds)
            n = col.size().getInfo()
            source = 'ERA5'
        if n == 0:
            print(f"{name}: Images=0")
            return {'status':'C1'}
        print(f"{name}: Images={n}, Source={source}")
        max_img = col.max()
        count = max_img.reduceRegion(
            reducer=ee.Reducer.count(),
            geometry=geom,
            scale=9000,
            maxPixels=1e9
        ).get(band).getInfo()
        count = 0 if count is None else int(count)
        print(f"{name}: Pixels={count}")
        if count == 0:
            return {'status':'C2'}
        valK = max_img.reduceRegion(
            reducer=ee.Reducer.mean(),
            geometry=geom,
            scale=9000,
            maxPixels=1e9
        ).get(band).getInfo()
        if valK is None or (isinstance(valK, float) and (math.isnan(valK) or not math.isfinite(valK))):
            return {'status':'C3'}
        if valK < 200 or valK > 350:
            return {'status':'C3'}
        valC = valK - 273.15
        print(f"{name}: Max T2m={valK:.2f} K ({valC:.2f} C)")
        return {'status':'OK', 'K':valK, 'C':valC}
    except Exception as e:
        # Keep output concise; emit diagnostic line and D
        print(f"{name}: Error: {str(e)[:60]}")
        return {'status':'D'}

res_st = daily_peak_t2m(st_geom, "St. Francis, KS")
res_dv = daily_peak_t2m(dv_geom, "Death Valley, CA")

# Prioritize failure conditions
statuses = {res_st['status'], res_dv['status']}
if 'D' in statuses:
    print("D")
elif 'C1' in statuses:
    print("C1")
elif 'C2' in statuses:
    print("C2")
elif 'C3' in statuses:
    print("C3")
else:
    ans = 'A' if res_st['C'] > res_dv['C'] else 'B'
    print(ans)
